// src/components/HeroModelDisplay.jsx

import { useState } from 'react'

export default function HeroModelDisplay() {
  const [hover, setHover] = useState(false)

  return (
    <div
      className="hero-model-wrapper"
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}>
      {/* Base PNG */}
      <img
        src="/assets/heroSection/BladeModel.png"
        className="hero-model-img base"
        alt="Hero"
      />

      {/* GIF */}
      <img
        src="/assets/gif/bladeGif.gif"
        className={`hero-model-img gif ${hover ? 'show' : ''}`}
        alt="Hero animated"
      />
    </div>
  )
}
